"""Rebuild offline bundles from original images; generated bytes are not duplicated in Git."""
from pathlib import Path
import base64
import hashlib
import json
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]

def image_data(record):
    path = Path(record['file'])
    if '..' in path.parts or path.is_absolute() or path.parts[0] not in {'assets', 'backgrounds'}:
        raise ValueError('Invalid bundled image path')
    data = (ROOT/'web'/path).read_bytes()
    if hashlib.sha256(data).hexdigest() != record['sha256']:
        raise ValueError('Image hash mismatch: ' + str(path))
    return 'data:' + record['content_type'] + ';base64,' + base64.b64encode(data).decode('ascii')

def main():
    library = json.loads((ROOT/'web/data/library.json').read_text())
    library['image_data'] = {key: image_data(asset) for key, asset in library['assets'].items()}
    (ROOT/'web/data/library.js').write_text('window.FLEET_LIBRARY=' + json.dumps(library, ensure_ascii=False, separators=(',', ':')) + ';\n')
    backgrounds = json.loads((ROOT/'web/data/nameplate-backgrounds.json').read_text())
    for row in backgrounds:
        row['data'] = image_data(row)
    (ROOT/'web/data/nameplate-backgrounds.js').write_text('window.FLEET_BACKGROUNDS=' + json.dumps(backgrounds, ensure_ascii=False, separators=(',', ':')) + ';\n')
    subprocess.run([sys.executable, str(ROOT/'android/prepare_web.py'), str(ROOT/'web')], cwd=ROOT, check=True)
    print('Prepared offline web and Android resources from original images.')

if __name__ == '__main__':
    main()
